// Test_ThrottlingPolicy_STATUS_WhenPropertiesConverted_RoundTripsWithoutLoss tests if a specific instance of ThrottlingPolicy_STATUS can be assigned to storage and back losslessly
func Test_ThrottlingPolicy_STATUS_WhenPropertiesConverted_RoundTripsWithoutLoss(t *testing.T) {
	t.Parallel()

	if testing.Short() {
		return
	}

	rapid.Check(t, func(t *rapid.T) {
		subject := ThrottlingPolicy_STATUSGenerator().Draw(t, "subject")
		// Copy subject to make sure assignment doesn't modify it
		copied := subject.DeepCopy()

		// Use AssignPropertiesTo() for the first stage of conversion
		var other storage.ThrottlingPolicy_STATUS
		err := copied.AssignProperties_To_ThrottlingPolicy_STATUS(&other)
		if err != nil {
			t.Fatal("AssignPropertiesTo: " + err.Error())
		}

		// Use AssignPropertiesFrom() to convert back to our original type
		var actual ThrottlingPolicy_STATUS
		err = actual.AssignProperties_From_ThrottlingPolicy_STATUS(&other)
		if err != nil {
			t.Fatal("AssignPropertiesFrom: " + err.Error())
		}

		// Check for a match
		match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
		if !match {
			actualFmt := pretty.Sprint(actual)
			subjectFmt := pretty.Sprint(subject)
			result := diff.Diff(subjectFmt, actualFmt)
			t.Error(result)
		}
	})
}

