// RunJSONSerializationTestForThrottlingPolicy_STATUS runs a test to see if a specific instance of ThrottlingPolicy_STATUS round trips to JSON and back losslessly
func RunJSONSerializationTestForThrottlingPolicy_STATUS(t *rapid.T) {
	subject := ThrottlingPolicy_STATUSGenerator().Draw(t, "subject")
	// Serialize to JSON
	bin, err := json.Marshal(subject)
	if err != nil {
		t.Fatal(err)
	}

	// Deserialize back into memory
	var actual ThrottlingPolicy_STATUS
	err = json.Unmarshal(bin, &actual)
	if err != nil {
		t.Fatal(err)
	}

	// Check for outcome
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		t.Error(result)
	}
}

